mapper.update:
update user_refresh_token
set status = #{status}, updated_at = #{updatedAt}
where id = #{id}

update user_refresh_token
set status = 'REPLACED', updated_at = #{updatedAt}
where id = #{id}
  and status = 'ACTIVE'
  and expires_at >= #{updatedAt}

update user_refresh_token
set status = 'REVOKED', updated_at = #{updatedAt}
where session_id = #{sessionId} and status = 'ACTIVE'
